import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BTLSZHNB.js";const m=JSON.parse('{"title":"takoform_queue_consumer","description":"Queue Consumer (edge.forms.takoform.com/v1alpha1, role attachment).","frontmatter":{"page_title":"takoform_queue_consumer Resource - takoform","subcategory":"Edge Platform Family","description":"Queue Consumer (edge.forms.takoform.com/v1alpha1, role attachment)."},"headers":[],"relativePath":"docs/resources/queue_consumer.md","filePath":"docs/resources/queue_consumer.md"}'),s={name:"docs/resources/queue_consumer.md"};function n(i,e,d,c,u,l){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="takoform-queue-consumer" tabindex="-1">takoform_queue_consumer <a class="header-anchor" href="#takoform-queue-consumer" aria-label="Permalink to &quot;takoform_queue_consumer&quot;">​</a></h1><p>Attaches one Module Worker as the batch consumer of one At-Least-Once Queue, invoking its queue handler with message batches and redelivering messages that were not acknowledged. Consumption is inward activation and therefore an attachment, never a binding. One queue has at most one consumer, so a second attachment against the same queue is refused. A handler that returns normally without settling anything acknowledges the whole batch; one that throws retries every message it had not already acknowledged. maxRetries counts REDELIVERIES only — the first delivery does not count toward it — so a message is delivered at most 1 + maxRetries times, and a message that exhausts them moves to dead_letter_queue when one is declared and is dropped otherwise. The dead-letter copy is a new message there: new identity, new acceptance timestamp, and an attempt count starting again at 1 (decision 0020). Because that transfer resets the attempt count, dead_letter_queue MUST NOT lead back: a destination resolving to the queue this consumer drains, or closing a cycle of any length through the dead-letter graph, is refused before any mutation, because an exhausted message would circulate forever instead of coming to rest (decision 0026).</p><p>This is an <code>attachment</code> resource: it connects a parent to inward activation (routes, domains, schedules, queue consumption). Deleting the attachment never deletes the parent.</p><p>This resource speaks the Host API v1alpha3 lane and requires provider v2.1.0 or later (source candidate; not yet published). The configured host selects and operates the concrete backend; no attribute names a vendor, target, credential, price, or implementation. See the <a href="../../examples/resources/takoform_queue_consumer/resource.tf">complete example</a>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>name</code> (String, required, forces replacement) — Portable resource name (<code>metadata.name</code>).</li><li><code>queue</code> (String, required, forces replacement) — Queue this consumer drains. Changing it replaces the attachment. Set the name of the target <code>AtLeastOnceQueue</code> resource.</li><li><code>worker</code> (String, required, forces replacement) — Module Worker whose queue handler receives the batches. Changing it replaces the attachment. Set the name of the target <code>ModuleWorker</code> resource.</li><li><code>max_batch_size</code> (Number, required) — Largest number of messages delivered in one batch. Between 1 and 100.</li><li><code>max_batch_timeout_seconds</code> (Number, required) — Longest time the host waits to fill a batch before delivering it, in seconds. Between 0 and 60.</li><li><code>max_retries</code> (Number, required) — How many times a failed batch is redelivered before its messages go to the dead-letter queue or are dropped. Between 0 and 100.</li><li><code>retry_delay_seconds</code> (Number, required) — Delay before a failed batch becomes deliverable again, in seconds. Between 0 and 43200.</li><li><code>dead_letter_queue</code> (String, optional) — Queue receiving messages that exhausted their retries. Without it, exhausted messages are dropped. It must not resolve to the queue this consumer drains, or close a cycle through other consumers&#39; dead-letter destinations; a host refuses either before any mutation. Set the name of the target <code>AtLeastOnceQueue</code> resource.</li><li><code>max_concurrency</code> (Number, required) — Largest number of concurrent batch invocations. Between 1 and 250.</li><li><code>space</code> (String, optional, forces replacement) — Exact opaque SpaceID; overrides the provider default.</li><li><code>create_timeout</code> / <code>update_timeout</code> / <code>delete_timeout</code> (String, optional) — Go durations bounding each operation (defaults <code>20m</code> / <code>20m</code> / <code>30m</code>).</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>uid</code> — host-issued immutable resource identity; delete and re-create yields a new UID.</li><li><code>generation</code> — desired-state generation; increments only when the portable desired spec changes. Updates fence on it.</li><li><code>revision</code> — representation revision; increments whenever the representation changes — a spec-changing update, new status, or new outputs. Deletes fence on it via <code>If-Match</code>.</li><li><code>conditions</code> — the complete status condition list the host reports, in its order. Each entry carries <code>type</code> (the closed <code>Ready</code> / <code>Reconciling</code> / <code>Degraded</code> / <code>Drifted</code> / <code>Blocked</code> / <code>Deleting</code> vocabulary), <code>status</code> (<code>True</code> / <code>False</code> / <code>Unknown</code>), the closed portable <code>reason</code>, an optional <code>message</code>, an optional non-portable <code>host_reason</code> naming exactly what is wrong, the <code>observed_generation</code> the status reflects, and <code>last_transition_time</code>. Conditions are host-rendered state: they change when this resource changes AND when a resource it depends on changes, with no desired spec changing anywhere, so they are read-only and a configuration must not assert them.</li><li><code>ready</code> — derived convenience: true when <code>conditions</code> carries the closed <code>Ready</code> condition with status <code>True</code>. Read <code>conditions</code> for the reason it is not.</li><li><code>outputs_json</code> — JSON-serialized <code>status.outputs</code> document (<code>&quot;{}&quot;</code> when empty).</li><li><code>form_api_version</code>, <code>form_kind</code>, <code>form_definition_version</code>, <code>form_schema_digest</code> — the exact immutable FormRef this state is bound to; reads dispatch on it.</li><li><code>form_package_digest</code> — audit-only package provenance; never part of resource identity, queries, or fences.</li><li><code>relation_drift_reason</code> — internal recovery only: <code>ExternalChange</code> or <code>DependencyMissing</code> while the host reports that a resource this one references was replaced or removed out of band, null otherwise. A refresh reports the break as a warning and keeps the resource in state; the next plan then proposes an in-place re-apply of the same desired state, which is all a host needs to re-resolve and re-pin every reference. It is provider-side recovery bookkeeping — no portable wire member carries it — and configurations must not depend on it.</li><li><code>pending_operation_id</code> — internal recovery only: the host operation id of a mutation the host accepted but that did not reach a terminal state before the operation deadline, null in steady state. A refresh consults it before it reads the resource, and it is cleared only once that operation settles. It is not resource identity and configurations must not depend on it.</li></ul><h2 id="state-continuity" tabindex="-1">State continuity <a class="header-anchor" href="#state-continuity" aria-label="Permalink to &quot;State continuity&quot;">​</a></h2><ul><li><strong>Reads dispatch on the recorded FormRef.</strong> <code>QueueConsumer</code> state is addressed under the exact <code>form_*</code> identity it records, not under this build&#39;s default create ref, so a resource created before the Form line advanced stays addressable as itself. An identity this provider build carries no codec for is a hard error naming that identity and the ones the build does carry; the provider never substitutes another exact FormRef, because a substituted query&#39;s &quot;not found&quot; is indistinguishable from deletion.</li><li><strong>A changed <code>uid</code> is an error, and state is kept.</strong> When the host serves a different <code>uid</code> under the recorded name, the resource this state was applied against is gone and something re-used its name. The provider reports a hard error naming both uids and keeps the resource in state. It does not re-bind — that would adopt a resource you never applied — and it does not remove state, which would make the next apply fail against the resource that does exist, with no plan left to repair it. Resolve it by importing the new incarnation explicitly, restoring the prior one, or deleting the host-side replacement.</li><li><strong>An unfinished mutation is resumed, not re-created.</strong> When <code>pending_operation_id</code> is set, a refresh asks the host about that operation before it reads the resource. While the operation is still running the resource may legitimately not exist yet, so its absence is not treated as deletion and the marker survives; a terminal success is verified against the exact identity and settles state; a terminal failure or an expired operation record defers to an exact read of the resource, which decides. Refresh again once the host settles.</li></ul><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_queue_consumer.example NAME</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_queue_consumer.example SPACE/NAME</span></span></code></pre></div><p>Both short forms bind state to this provider build&#39;s default create FormRef. To adopt a resource created under an EARLIER definition version of this Form, name the exact identity instead. The import ID is then one JSON object — not a delimiter-joined string, because a SpaceID is opaque UTF-8 whose only forbidden character is <code>/</code>, so no separator can escape it safely:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_queue_consumer.example \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &#39;{&quot;space&quot;:&quot;prod&quot;,&quot;apiVersion&quot;:&quot;edge.forms.takoform.com/v1alpha1&quot;,&quot;kind&quot;:&quot;QueueConsumer&quot;,&quot;definitionVersion&quot;:&quot;0.1.0&quot;,&quot;schemaDigest&quot;:&quot;sha256:…&quot;,&quot;name&quot;:&quot;…&quot;}&#39;</span></span></code></pre></div><p><code>space</code> is optional and falls back to the provider default; the four FormRef members are all-or-nothing. An identity this provider build carries no codec for is refused, naming the identities it does carry — it is never silently rebound to the default.</p>`,15)])])}const p=t(s,[["render",n]]);export{m as __pageData,p as default};
